window.CASE_ONE_LESSONS = {"english": {"path": "./h5p/case-one-english", "duration": 144.41666666666666, "questions": 2, "speaker": "en-IN-PrabhatNeural", "captions": [[0.2, 4.75, "Can a simple wire act like a magnet? Let us investigate."], [4.95, 13.0, "Our circuit has a battery, switch, copper wire, resistor, and an ammeter connected in series."], [13.2, 21.75, "Let us look inside the copper wire. We are enlarging a tiny part to see a teaching model of its particles."], [21.95, 33.666666666666664, "The small blue dots are electrons. The copper-coloured spheres are copper ions, vibrating around fixed positions. These colours help us tell them apart."], [33.86666666666667, 44.75, "With the switch OFF, electrons move randomly. There is no net flow around the circuit, so no magnetic field from a current in this wire."], [44.95, 54.0, "Switch ON. Electrons now drift to the right. This net flow creates current and a magnetic field around the wire."], [54.2, 63.75, "Electrons drift from negative to positive. Moving yellow arrows show conventional current in the opposite direction: positive to negative."], [63.95, 74.25, "The green circles show the magnetic field around the wire. Their arrows show the field direction. The field remains while current flows."], [74.45, 83.41666666666667, "Bring a magnetic compass near the wire. Its needle turns. That deflection helps us detect the magnetic field."], [83.61666666666667, 93.5, "The ammeter reads half an ampere. Here, the compass deflection is about twenty-five degrees. Remember these starting readings."], [93.7, 103.58333333333333, "Keep the wire and compass position the same. Now double the current. Compare the before and now readings on the ammeter and compass."], [103.78333333333333, 121.41666666666666, "One ampere: the wire’s field is twice as strong at the same distance. More circles represent the stronger field. The needle turns from twenty-five to about forty-three degrees: about eighteen degrees further. The angle does not double."], [121.61666666666666, 127.58333333333333, "Reduce the current again. The field weakens, and the compass needle turns back."], [127.78333333333333, 144.41666666666666, "To summarize what we learned: moving charge produces current and a magnetic field. A compass detects it. More current means a stronger field. If current stops, the wire's field disappears; Earth's magnetic field remains."]]}, "hinglish": {"path": "./h5p/case-one-hinglish", "duration": 187.83333333333331, "questions": 2, "speaker": "hi-IN-SwaraNeural", "captions": [[0.2, 8.083333333333334, "क्या एक साधारण तार, चुंबक की तरह असर दिखा सकता है? आइए, प्रयोग करके समझें।"], [8.283333333333333, 19.083333333333336, "इस परिपथ में बैटरी, स्विच, ताँबे का तार, प्रतिरोधक और श्रेणीक्रम में जुड़ा ऐमीटर है। ऐमीटर विद्युत धारा मापता है।"], [19.283333333333335, 29.16666666666667, "अब ताँबे के तार के अंदर झाँकते हैं। उसके बहुत छोटे हिस्से को बड़ा करके, कणों का एक समझाने वाला मॉडल देखेंगे।"], [29.36666666666667, 44.41666666666667, "छोटे नीले बिंदु इलेक्ट्रॉन हैं। ताँबे के रंग वाले गोले, ताँबे के आयन हैं। आयन अपनी जगह के आसपास कंपन करते हैं। दोनों को पहचानने के लिए अलग रंग दिखाए हैं।"], [44.616666666666674, 59.16666666666667, "स्विच खुला है। इलेक्ट्रॉन अलग-अलग दिशाओं में चलते हैं। परिपथ में उनका किसी एक दिशा में कुल बहाव नहीं है, इसलिए तार में विद्युत धारा से बनने वाला चुंबकीय क्षेत्र नहीं है।"], [59.366666666666674, 72.16666666666667, "अब स्विच बंद करते हैं। इलेक्ट्रॉनों का दाईं ओर बहाव शुरू होता है। इसी बहाव से विद्युत धारा बहती है और तार के चारों ओर चुंबकीय क्षेत्र बनता है।"], [72.36666666666667, 87.08333333333334, "इलेक्ट्रॉन, ऋणात्मक से धनात्मक सिरे की ओर बहते हैं। चलते हुए पीले तीर विद्युत धारा की प्रचलित दिशा दिखाते हैं। यह उलटी दिशा है, धनात्मक से ऋणात्मक सिरे की ओर।"], [87.28333333333335, 100.91666666666667, "हरे वृत्त, तार के चारों ओर चुंबकीय क्षेत्र दिखाते हैं। उन पर तीर, क्षेत्र की दिशा बताते हैं। जब तक विद्युत धारा बहती है, यह क्षेत्र बना रहता है।"], [101.11666666666667, 112.0, "तार के पास चुंबकीय कम्पास रखते हैं। उसकी सुई मुड़ती है। सुई के इस विक्षेप से हमें चुंबकीय क्षेत्र का पता चलता है।"], [112.2, 123.16666666666667, "ऐमीटर पर आधा ऐम्पियर है। हमारे मॉडल में कम्पास की सुई लगभग पच्चीस डिग्री मुड़ी है। इन शुरुआती मापों को याद रखिए।"], [123.36666666666667, 135.0, "तार और कम्पास की जगह वही रखते हैं। अब विद्युत धारा दोगुनी करते हैं। ऐमीटर और कम्पास के पहले और अब के मापों की तुलना कीजिए।"], [135.2, 155.25, "अब एक ऐम्पियर है। उतनी ही दूरी पर तार का चुंबकीय क्षेत्र दोगुना है। ज़्यादा वृत्त अधिक प्रबल क्षेत्र दिखाते हैं। सुई पच्चीस से लगभग तैंतालीस डिग्री पर आ गई है, यानी लगभग अठारह डिग्री और मुड़ी है। कोण दोगुना नहीं होता।"], [155.45, 163.66666666666666, "विद्युत धारा फिर कम करते हैं। चुंबकीय क्षेत्र कमज़ोर होता है और कम्पास की सुई वापस मुड़ती है।"], [163.86666666666665, 187.83333333333331, "आइए, जो सीखा उसे दोहराएँ। आवेश के एक दिशा में कुल बहाव से विद्युत धारा और चुंबकीय क्षेत्र बनते हैं। कम्पास इस क्षेत्र का पता लगाता है। ज़्यादा धारा से क्षेत्र प्रबल होता है। धारा रुकने पर तार का क्षेत्र समाप्त होता है, लेकिन पृथ्वी का चुंबकीय क्षेत्र रहता है।"]]}};
